// Shuffle Sharding: Assign each tenant K=4 workers out of N=8 total workers.
// Number of unique virtual shards = C(8, 4) = 8! / (4! * 4!) = 70 virtual shards!
// If 1 noisy tenant saturates all 4 of its assigned workers, only 1/70 (1.4%) of other
// tenants share all 4 workers—compared to 1/2 (50%) in standard 2-shard partitioning!
export function assignShuffleShardWorkers(
  tenantId: string,
  totalWorkersN = 8,
  shardSizeK = 4
): number[] {
  const selected = new Set<number>();
  let salt = 0;
  while (selected.size < shardSizeK) {
    const hash = fnv1aHash(tenantId + ':' + salt++);
    selected.add(hash % totalWorkersN);
  }
  return Array.from(selected);
}
